parameters.jsCode:
// [10] Validate the generated reply — Code node
// Deterministic only. No extra LLM call: the router already narrowed the context, so what is left
// to check is mechanical — invented prices, internal vocabulary, URLs, fake actions, pressure,
// length, one-question rule.

const ctx = $('Fetch KB').first().json;

// No output-parser sub-node, so the reply arrives as plain text in `.text`. Same tolerant parse as
// Merge State: a ```json fence, a sentence before the object or a trailing comma all still work.
const parseJson = (v) => {
  if (v && typeof v === 'object') return v;
  let s = String(v == null ? '' : v).trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a === -1 || b <= a) return null;
  s = s.slice(a, b + 1);
  try { return JSON.parse(s); } catch (e) {}
  try { return JSON.parse(s.replace(/,\s*([}\]])/g, '$1')); } catch (e) { return null; }
};

const raw = $input.first().json;
let gen = parseJson(raw.output ?? raw.text ?? raw.response ?? raw);

const fail = (reason) => [{ json: { ...ctx, gen: gen || {}, ok: false, fallback_reason: reason } }];

// Sometimes the model forgets the envelope and answers in plain prose. The ANSWER is usually fine —
// throwing it away and showing "I lost the thread on that one" punishes the visitor for a
// formatting slip. If what came back reads like a reply rather than a broken object, keep it and
// let every check below judge it exactly as it would judge a parsed one.
if (!gen || typeof gen.reply !== 'string') {
  const prose = String(raw.output ?? raw.text ?? raw.response ?? '').trim();
  if (prose && !prose.includes('{') && prose.length >= 40 && prose.length <= 2000) {
    gen = { reply: prose, cta_intent: 'none', asked_question: null, answer_options: [], claims: [],
            handoff_reason: null, recommended_services: [], confidence: 0.5, _salvaged: true };
  } else {
    return fail('invalid_json');
  }
}

// A narrowing turn has a contract: a question, and options they can tap. The model sometimes
// returns only the observation — "you mentioned wanting a website but haven't shared what type" —
// with asked_question null and answer_options empty. That is a dead end that blames the visitor
// for the model's own missing turn, so it never ships.
if (ctx.narrow_first && (!gen.asked_question || !Array.isArray(gen.answer_options) || gen.answer_options.length < 3)) {
  return fail('narrow_incomplete');
}
// "You want a website, which is a great start. What kind of business is it for?" asks the right
// thing and gives the visitor nothing: it restates their message and stops. A narrowing turn is
// short, not empty — it still has to say why the answer depends on what it is asking.
if (ctx.narrow_first && gen.reply.trim().length < 180) return fail('narrow_incomplete');

let reply = gen.reply.trim();

// strip sycophancy rather than failing the whole turn
reply = reply.replace(/^(absolutely|certainly|great question|that's an excellent question|great choice|sure)[!.,]?\s*(—|-)?\s*/i, '');
reply = reply.replace(/\bI'd be (thrilled|delighted|happy) to\b/gi, 'I can');

// Answering two or three questions legitimately needs more room than answering one.
const asked = (ctx.questions || []).length;
const maxLen = asked >= 2 ? 1500 : 1200;
const maxParas = asked >= 2 ? 6 : 5;

if (reply.length < 20) return fail('too_short');
if (reply.length > maxLen || reply.split(/\n\s*\n/).length > maxParas) return fail('too_long');
if ((reply.match(/\?/g) || []).length > 1) return fail('too_many_questions');
if (/https?:\/\/|www\.|\[[^\]]+\]\([^)]+\)|<[a-z][^>]*>/i.test(reply)) return fail('url_in_reply');

// Internal vocabulary must never surface — but ONLY genuinely internal vocabulary.
// Words like workflow, automation, database, API and integration are the company's own product
// language ("workflow audit" is a named step of the AI Automation service), so banning them
// rejects perfectly good answers. What must never appear is the advisor talking about ITSELF:
// its prompt, its retrieval, its vendors, or the act of looking something up.
const LEAKS = [
  /\bsystem prompt\b/i,
  /\bmy (instructions|guidelines|prompt|training|configuration|rules)\b/i,
  /\bknowledge base\b/i,
  /\b(n8n|notion|openai|anthropic|langchain|groq)\b/i,
  /\bgpt-?\d/i,
  /\b(claude|llm|large language model|language model)\b/i,
  /\b(vector (database|store)|embeddings?|retrieval[- ]augmented|rag)\b/i,
  /\b(the|my) (documents?|context|data|records|files) (I|i) (have|was given|can see)\b/i,
  /\bin my (data|records|files|context)\b/i,
  /\bi (looked|searched|checked) (this|that|it) up\b/i,
  /\b(based on|according to) (the|my) (documents?|context|data|knowledge)\b/i,
];
for (const p of LEAKS) if (p.test(reply)) return fail('internal_leak');

// actions the system cannot perform, and promises nobody authorised
// An adverb slips in more often than not — "I have already emailed you" — so allow a word or two
// between the verb phrase and the action.
if (/\b(I('ve| have)( \w+){0,2} (sent|emailed|forwarded|booked|scheduled|notified|passed (this|it) (on|along))|someone( \w+){0,4} will (contact|call|email|reach out)|the team (has|have)( \w+){0,2} (reviewed|seen|read)|I('ll| will)( \w+){0,2} (send|email|book|schedule|forward))\b/i.test(reply) && !ctx.S.flags.lead_ok) return fail('fake_action');
if (/\bwithin (\d+|one|two|a few|24|48)\s*(hours?|days?|business days?)\b/i.test(reply)) return fail('fake_action');
// "we can send you a plan" is the same broken promise in the first person plural — nothing is sent.
// But a good answer that ends with one unkeepable sentence should lose the sentence, not the answer:
// throwing the whole turn away costs the visitor three useful paragraphs to save them one bad line.
// Strip it; only fail if too little survives to be worth sending.
// "I can connect you with the team" is the same unkeepable promise as "I can send you a plan" —
// nothing connects anyone, and the visitor then waits for an introduction that never comes. The
// verb list is what makes or breaks this guard, so it covers the whole family, not just sending.
const PROMISE = /[^.!?\n]*\b(we|i|let\s+me|let\s+us)\s*('ll|'d| can| could| will| would)?\s*(send|email|share|put together|prepare|draft|deliver|connect|introduce|arrange|refer|hand|pass|set up|get)\s+(you|over|a|an|the|it|us)\b[^.!?\n]*[.!?]?/gi;
if (PROMISE.test(reply)) {
  const stripped = reply.replace(PROMISE, '').replace(/[ \t]{2,}/g, ' ').replace(/\n{3,}/g, '\n\n').replace(/\(\s*\)/g, '').trim();
  if (stripped.length >= 120) {
    reply = stripped;
    // The question it asked was probably the promise itself; do not keep it in state.
    if (gen.asked_question && /\b(send|email|share|prepare)\b/i.test(gen.asked_question)) gen.asked_question = null;
  } else {
    return fail('fake_action');
  }
}

// Pricing talk the visitor never asked for reads as defensive and points at the hidden number.
const askedMoney = /\b(cost|price|pricing|charge|budget|fee|rate|expensive|afford|how much)\b/i
  .test([ctx.payload.message, ...(ctx.questions || [])].join(' '));
if (!askedMoney && /\b(pricing (is|isn't|is not)|not published|exact price|price is set|scope of work is defined|free growth plan)\b/i.test(reply)) return fail('unprompted_pricing');

if (/\b(act now|limited (time|spots?)|only (a )?few (spots|places)|don't miss out|you('re| are) missing out|last chance|hurry|best option for you)\b/i.test(reply)) return fail('pressure');

// ── pricing: every amount must appear in a pricing-allowed doc that was actually fetched ──
const allowed = new Set(ctx.allowed_prices || []);
const amounts = [];
for (const m of reply.matchAll(/(?:\$|usd\s?)\s?(\d{1,3}(?:,\d{3})*(?:\.\d+)?)(\s*k\b)?/gi)) {
  const n = parseFloat(m[1].replace(/,/g, '')) * (m[2] ? 1000 : 1);
  amounts.push(String(Math.round(n)));
}
const percents = (reply.match(/(\d{1,3})\s?%/g) || []).map(p => p.replace(/\s/g, '').replace('%', '') + '%');
if (amounts.length && ctx.pricing_mode !== 'published') return fail('invented_price');
for (const v of amounts) if (!allowed.has(v)) return fail('invented_price');
for (const p of percents) if (!allowed.has(p)) return fail('invented_price');

// ── grounding: company claims require context ──
let claims = Array.isArray(gen.claims) ? gen.claims.slice(0, 8) : [];
// A narrowing turn states no company facts — it asks a question. But we also require it to name
// Simplified Startup, and the model files that sentence as a claim, which the gate below then
// rejects for having no supporting document. That is how a good turn became "I don't have enough
// to answer that accurately". Naming who is speaking is not a claim about the work; a promise
// about what the work involves still is, so that is what gets checked here instead.
// This only matters when NOTHING was retrieved. With documents in hand the gate below does the
// real work, and blocking the word "offers" here rejected "Simplified Startup offers fast, modern
// websites" — the company naming the prompt asks for — and sent a good narrowing turn to the
// fallback. Unsupported, what must not appear is a concrete promise about the work itself.
if (ctx.narrow_first && ctx.support === 'NOT_SUPPORTED') {
  if (/\b(we|our team|simplified startup)\b[^.!?]{0,60}\b(includes?|guarantees?|delivers?)\b/i.test(reply)) return fail('narrow_incomplete');
  if (/\b\d+\s*(day|week|month|year)s?\b/i.test(reply)) return fail('narrow_incomplete');
  claims = [];
}
if (ctx.support === 'NOT_SUPPORTED' && claims.length > 0) return fail('unsupported_claim');
if (ctx.support === 'NOT_SUPPORTED' && /\b(simplified startup|our team|we)\b.{0,40}\b(typically|usually|often|around|about|most clients|guarantee)\b/i.test(reply)) return fail('unsupported_claim');
// A claim naming a figure or timeframe must have that string somewhere in the fetched docs.
for (const claim of claims) {
  const facts = claim.match(/\b\d+[\d,.%]*\s*(weeks?|days?|months?|years?|%)?\b/gi) || [];
  for (const f of facts) {
    const bare = f.trim().replace(/,/g, '');
    if (bare.length < 2) continue;
    if (!ctx.kb_context.replace(/,/g, '').toLowerCase().includes(bare.toLowerCase())) return fail('added_specificity');
  }
}

if (!ctx.allowed_cta.includes(gen.cta_intent)) gen.cta_intent = 'none';
gen.reply = reply;
gen.claims = claims;
gen.answer_options = Array.isArray(gen.answer_options) ? gen.answer_options.slice(0, 5) : [];
gen.recommended_services = Array.isArray(gen.recommended_services) ? gen.recommended_services.slice(0, 3) : [];
if (typeof gen.confidence !== 'number') gen.confidence = 0.5;

return [{ json: { ...ctx, gen, ok: true, fallback_reason: null } }];

// Advisor call errored or returned nothing parseable — hand the fallback node a reason.
const ctx = $('Fetch KB').first().json;
return [{ json: { ...ctx, gen: null, ok: false, fallback_reason: 'llm_failure' } }];

// [11] Safe replies + fallbacks — Code node
// Every path converges here: safe intents that skipped the advisor call, validated replies, and
// failures. None of these may hint at how the advisor works, and none may be a dead end — every
// one gives the visitor something and a way forward.

const x = $input.first().json;
const S = x.S;
const intent = x.intent;
const a = (k) => S.attrs[k]?.v || null;
const pick = (arr) => arr[S.turn % arr.length];

const T = {
  PROMPT_INJECTION: pick([
    "I can help with what Simplified Startup does and whether the team is a fit for your business, but not with anything behind the scenes.\n\nWhat are you working on?",
    "That's not something I can get into. What I can do is help you work out which kind of support fits your situation — tell me what's on your plate.",
  ]),
  INTERNAL_INFO: pick([
    "I can't get into how things work behind the scenes, but I can tell you what the team takes on and what a sensible next step looks like.\n\nWhat are you trying to achieve?",
    "That's not something I can detail. Tell me what you're trying to build or fix, and I'll tell you where Simplified Startup fits — and where it doesn't.",
  ]),
  UNRELATED: pick([
    "I'm focused on startup strategy, growth, product, web, marketing, sales and automation.\n\nIf there's a business problem behind this, tell me what's stuck and I'll help you think it through.",
    "That's outside what I'm here for. I'm best on building, launching and growing a business — what are you working on?",
  ]),
  GENERAL_KNOWLEDGE: "I'm not the right place for that one. I'm here for startup strategy, growth, product, web, marketing, sales and automation — if there's a business question underneath it, I'm glad to take that on.",
  ABUSIVE: "I'll stay on the business side of things. If there's something you're trying to build or grow, I'm here for that.",
  VENDOR_PITCH: "Thanks for reaching out. I'm set up to help founders exploring Simplified Startup's services rather than partnerships or vendor offers — the contact email on the website is the right place for that.",
  SENSITIVE: "I'm sorry you're dealing with that. It's outside what I should advise on — a qualified professional, or a person on the team if it concerns Simplified Startup directly, is the right next step.\n\nIf it's useful, I'm still here for the business side.",
  CLOSING: "I'm best at startup strategy, growth, product, web, marketing, sales and automation, so I'll leave it there. If a business question comes up, come back any time — or book a conversation with the team from the site.",
  HUMAN_REQUEST: S.contact.email
    ? "Understood. You can book a time with the team directly, and they'll have the context from this conversation."
    : "Of course. The team is the right next step for this. What's the best email for them to reach you — or you can book a time directly.",
  PRICING_UNKNOWN: (() => {
    const svc = a('requested_service')?.replace(/-/g, ' ');
    return `Pricing${svc ? ` for ${svc}` : ''} comes down to scope and which part of the team is involved, and I'd rather not give you a number that turns out to be wrong.\n\nWhat usually moves it most is how much already exists versus how much is built from scratch. Tell me a bit about what you're starting from and I can show you which kind of engagement you're looking at — and the team scopes it properly in writing.`;
  })(),
  KB_EMPTY: "I don't have that one confirmed, and I'd rather say so than guess.\n\nI can still help you think it through — what's driving the question? If it's a decision you're weighing, I can usually tell you what actually changes the answer.",
  UNGROUNDED: "I don't have enough to answer that accurately, and a confident wrong answer is worse than none.\n\nTell me a little more about what you're trying to achieve and I can point you in the right direction — or the team can answer it directly.",
  NARROW: "Before pointing you anywhere, Simplified Startup starts with who the work is actually for. It is the thing that changes everything else — what earns trust for a restaurant is usually the wrong first move for a B2B software company, and building before that is settled is how most of the budget gets spent twice.\n\nWhat kind of business is this for?",
  LLM_FAILURE: "I lost the thread on that one. Could you say it another way, or tell me a bit more about what you're trying to achieve?",
  BROKEN: "Let me keep this simple: tell me the one thing that's most stuck right now, and I'll help you work out where to start.",
};

let reply = null, fallback = null, fbOptions = [];

if (S.flags.closing && ['UNRELATED', 'GENERAL_KNOWLEDGE'].includes(intent)) { reply = T.CLOSING; fallback = 'closing'; }
else if (x.route === 'safe' && T[intent]) { reply = T[intent]; fallback = intent.toLowerCase(); }
else if (intent === 'HUMAN_REQUEST' && !x.gen) { reply = T.HUMAN_REQUEST; fallback = 'human_request'; }
else if (x.ok && x.gen?.reply) { reply = x.gen.reply; }
else {
  const r = x.fallback_reason || 'unknown';
  if (x.kb_empty && ['COMPANY', 'SERVICE', 'PRICING', 'BUYING_INTENT'].includes(intent)) { reply = T.KB_EMPTY; fallback = 'kb_empty'; }
  else if (r === 'narrow_incomplete') {
    reply = T.NARROW;
    fallback = 'narrow_incomplete';
    // The chip row is the point of a narrowing turn, and this path exists precisely because the
    // model returned none. The question above is fixed, so fixed answers to it are the right ones.
    fbOptions = ['Shop or e-commerce', 'Restaurant or hospitality', 'Clinic or healthcare', 'Services or consulting', 'Something else'];
  }
  else if (intent === 'PRICING' || r === 'invented_price') { reply = T.PRICING_UNKNOWN; fallback = 'pricing_unknown'; }
  else if (['unsupported_claim', 'added_specificity', 'internal_leak', 'url_in_reply', 'fake_action', 'pressure', 'unprompted_pricing'].includes(r)) { reply = T.UNGROUNDED; fallback = 'ungrounded:' + r; }
  else if (['invalid_json', 'llm_failure'].includes(r)) { reply = T.LLM_FAILURE; fallback = 'llm_failure'; }
  else if (['too_long', 'too_short', 'too_many_questions'].includes(r)) { reply = T.BROKEN; fallback = r; }
  else { reply = T.UNGROUNDED; fallback = 'unknown:' + r; }
}

const gen = (x.gen && !fallback) ? x.gen : {
  reply, cta_intent: 'none', asked_question: null, answer_options: fbOptions, claims: [], uses_pricing: false,
  handoff_reason: intent === 'HUMAN_REQUEST' ? 'explicit_request' : (fallback === 'kb_empty' || String(fallback).startsWith('ungrounded') ? 'no_kb' : null),
  recommended_services: [], confidence: fallback ? 0.3 : 0.6,
};

S.flags.low_conf = (fallback || gen.confidence < 0.4) ? S.flags.low_conf + 1 : 0;

return [{ json: { ...x, S, reply, gen, fallback } }];

// [12] Qualification + CTA — Code node (deterministic; docs/04 is the spec)
// The model proposed a cta_intent; this table decides what the visitor actually sees.

const SITE = 'https://simplifiedstartup.com';

const x = $input.first().json;
const S = x.S;
const { gen, intent } = x;
const sig = x.signals || {};
const a = (k) => S.attrs[k]?.v || null;
const c = (k) => S.attrs[k]?.c || 0;

const NAMES = {
  'digital-marketing': 'Digital Marketing', 'website-development': 'Website Development', 'branding-growth': 'Branding & Growth',
  'sales-lead-gen': 'Sales & Lead Generation', 'ai-automation': 'AI Automation', 'business-advisory': 'Business & Startup Advisory',
  'talent-staffing': 'Talent & Staffing', 'bookkeeping': 'Bookkeeping & Accounting',
};
const SLUGS = Object.keys(NAMES);

// ── recommendations ───────────────────────────────────────────────────────
const proposed = (gen.recommended_services || []).filter(s => SLUGS.includes(s));
if (proposed.length && x.support !== 'NOT_SUPPORTED' && !x.fallback) {
  S.rec = [proposed[0]];
  S.sec_rec = proposed.slice(1, 3);
  S.reasoning = (gen.reply.split(/\n\s*\n/)[1] || gen.reply.split(/\n\s*\n/)[0] || '').slice(0, 200);
}

// ── scores (never shown to the visitor) ───────────────────────────────────
const signals = [];
let it = 0;
const add = (w, label) => { it += w; signals.push(label); };
if (sig.hire) add(0.40, 'hire');
if (sig.call) add(0.35, 'call');
if (sig.price || intent === 'PRICING') add(0.20, 'price');
if (sig.timeline_near || ['asap', '1_3_months'].includes(a('timeline'))) add(0.20, 'timeline≤3m');
else if (a('timeline') === '3_6_months') add(0.10, 'timeline 3–6m');
if (a('decision_stage') === 'comparing') add(0.15, 'comparing');
if (a('decision_stage') === 'ready') add(0.30, 'ready');
if (a('budget_signal')) add(0.15, 'budget');
if (S.contact.company || a('website')) add(0.10, 'company/site');
if (S.contact.email) add(0.25, 'email');
if (sig.just_researching) add(-0.30, 'researching');
if (S.flags.vendor_pitch) add(-0.60, 'vendor');
it = Math.max(0, Math.min(1, Math.max(it, (S.score.intent || 0) * 0.85)));

let fit = 0;
if (S.rec.length && (c('primary_problem') >= 0.6 || c('primary_goal') >= 0.6)) fit += 0.5;
const bt = (a('business_type') || '').toLowerCase();
if (bt && !/enterprise|fortune|government|personal|hobby|student/.test(bt)) fit += 0.3;
if (['pre_launch', 'early_revenue', 'growing'].includes(a('business_stage'))) fit += 0.2;
if (S.flags.no_kb >= 2 && intent === 'SERVICE') fit -= 0.5;
fit = Math.max(0, Math.min(1, Math.max(fit, (S.score.fit || 0) * 0.9)));

const clarity = Number(((c('business_stage') + c('business_type') + c('primary_problem') + c('primary_goal')) / 4).toFixed(2));

let quality = 'Cold';
if (S.flags.vendor_pitch) quality = 'Cold';
else if (it >= 0.70 && fit >= 0.60) quality = 'Hot';
else if (it >= 0.45 && fit >= 0.50) quality = 'Warm';
else if (it >= 0.20 || clarity >= 0.50) quality = 'Exploring';

const prevQuality = S.score.quality;
S.score = { intent: Number(it.toFixed(2)), fit: Number(fit.toFixed(2)), clarity, quality, signals };
S.flags.hot = quality === 'Hot' ? S.flags.hot + 1 : 0;
if (S.phase === 'RECOMMENDING' && ['Warm', 'Hot'].includes(quality)) S.phase = 'QUALIFYING';

// ── handoff ───────────────────────────────────────────────────────────────
// "I want a website" is how a conversation opens, not how it ends. A hire signal on the opening
// turn is interest, not a decision — treating it as one means asking for an email before saying
// anything useful, which is the fastest way to lose the lead. Wait until they have told us
// something, or until the conversation has actually gone somewhere.
let handoff = S.phase === 'HANDOFF' || S.flags.handoff || a('decision_stage') === 'ready';
if (sig.hire && (S.turn >= 2 || (c('business_type') + c('primary_problem')) >= 0.6)) handoff = true;
if (S.flags.hot >= 2 || S.flags.low_conf >= 2 || S.flags.no_kb >= 2) handoff = true;
if (gen.handoff_reason) handoff = true;
// The model set handoff_reason on the opening turn and the visitor got "Book a free consultation"
// under a brochure, before telling us a single thing about their business. Asking to close on turn
// one is asking before answering. Only their own explicit request overrides this.
if (x.narrow_first && intent !== 'HUMAN_REQUEST' && !sig.call && !sig.negotiation) handoff = false;
if (handoff && !['CAPTURING', 'HANDOFF'].includes(S.phase)) S.phase = (S.contact.email || S.flags.declined) ? 'HANDOFF' : 'CAPTURING';
if (S.phase === 'CAPTURING' && S.contact.email) S.phase = 'HANDOFF';

let ask_contact = null;
if (S.phase === 'CAPTURING' && !S.flags.declined) ask_contact = !S.contact.email ? 'email' : (!S.contact.name ? 'name' : null);
// Fetch KB already ruled this out for a narrowing turn, but ask_contact is derived from the phase
// and gets recomputed here — so the email request came back underneath the question anyway. Nobody
// hands over an address before they have been told anything.
if (x.narrow_first) ask_contact = null;

// Asking on every single turn is nagging, and a visitor who did not answer the first time is not
// going to answer the fourth. Ask, then leave it alone for two turns, and give up after three.
S.flags.email_asks = S.flags.email_asks || 0;
S.flags.last_email_ask = S.flags.last_email_ask || 0;
if (ask_contact === 'email') {
  const tooSoon = S.flags.email_asks > 0 && (S.turn - S.flags.last_email_ask) < 3;
  if (S.flags.email_asks >= 3 || tooSoon) ask_contact = null;
  else { S.flags.email_asks += 1; S.flags.last_email_ask = S.turn; }
}

if (ask_contact === 'email' && !/email/i.test(x.reply)) {
  x.reply += "\n\nIf you'd like the team to pick this up with context, what's the best email to reach you — or you can book a time directly.";
}

// ── CTA table (first match wins) ──────────────────────────────────────────
const build = (id) => {
  if (id === 'consult') return { id, label: 'Book a free consultation', url: `${SITE}/start-project`, kind: 'link' };
  if (id === 'pricing') return { id, label: 'See published pricing', url: `${SITE}/pricing`, kind: 'link' };
  if (id.startsWith('service:')) { const s = id.slice(8); return SLUGS.includes(s) ? { id, label: `Explore ${NAMES[s]}`, url: `${SITE}/${s}`, kind: 'link' } : null; }
  if (id === 'tell_more') return { id, label: 'Tell me more about your situation', kind: 'suggest', text: "Here's more detail on my situation: " };
  if (id === 'explore_first') return { id, label: 'Help me explore the options first', kind: 'suggest', text: 'Help me explore the options first' };
  if (id === 'talk_team') return { id, label: 'Talk to the team', kind: 'suggest', text: "I'd like to talk to the team" };
  return null;
};
const shownRecently = (id, n = 1) => S.cta_history.slice(-n).some(h => h.ids.includes(id));
const primary = S.rec[0];
const t = S.turn;
const ids = [];
let reason = 'none';

if (handoff) { ids.push('consult'); if (!S.contact.email && !S.flags.declined && ask_contact !== 'email') ids.push('talk_team'); reason = 'handoff'; }
else if (['PROMPT_INJECTION', 'INTERNAL_INFO', 'ABUSIVE', 'SENSITIVE', 'VENDOR_PITCH'].includes(intent)) reason = 'safe_path';
else if (['UNRELATED', 'GENERAL_KNOWLEDGE'].includes(intent)) { if (S.flags.offtopic >= 3) ids.push('tell_more'); reason = 'unrelated'; }
else if (x.kb_empty && ['COMPANY', 'PRICING', 'SERVICE'].includes(intent)) { ids.push('consult'); reason = 'kb_unavailable'; }
else if (intent === 'PRICING' && x.pricing_mode === 'published') { ids.push('pricing'); if (['Warm', 'Hot'].includes(quality) && !shownRecently('consult')) ids.push('consult'); reason = 'pricing_supported'; }
else if (intent === 'PRICING') { if (!shownRecently('consult')) ids.push('consult'); reason = 'pricing_unknown'; }
else if (quality === 'Hot') { if (!shownRecently('consult')) ids.push('consult'); reason = 'high_intent'; }
else if (quality === 'Warm' && ['RECOMMENDING', 'QUALIFYING'].includes(S.phase)) { ids.push('talk_team'); if (primary && !shownRecently(`service:${primary}`, 2)) ids.push(`service:${primary}`); reason = 'warm_recommendation'; }
else if (S.phase === 'RECOMMENDING' && primary && !shownRecently(`service:${primary}`, 2)) { ids.push(`service:${primary}`); reason = 'service_education'; }
// Once the advisor has answered from the knowledge base AND we know what kind of business this is,
// the visitor has had the useful part. Another "tell me more about your situation" is a third
// question wearing a button, and it is where the conversation quietly ends. Offer the next step.
else if (t >= 2 && !x.fallback && ['SUPPORTED', 'PARTIAL'].includes(x.support) && c('business_type') >= 0.6) {
  ids.push('consult');
  if (primary && !shownRecently(`service:${primary}`, 2)) ids.push(`service:${primary}`);
  reason = 'answered_offer_next_step';
}
else if (clarity < 0.4 && t >= 2) { ids.push('tell_more'); reason = 'insufficient_info'; }
else if (['Cold', 'Exploring'].includes(quality) && t <= 2) reason = 'too_early';
else if (quality === 'Exploring' && t >= 3 && !S.flags.explore_shown) { ids.push('explore_first'); S.flags.explore_shown = true; reason = 'low_intent'; }

const cta = ids.map(build).filter(Boolean).slice(0, 2);
if (cta.length) S.cta_history.push({ t, ids: cta.map(x2 => x2.id), reason });
if (S.cta_history.length > 12) S.cta_history = S.cta_history.slice(-12);

let suggestions = (gen.answer_options || []).filter(s => typeof s === 'string' && s.length <= 60).slice(0, 5);
if (S.phase === 'ADVISORY' && !suggestions.length) suggestions = ['Get our first paying customers', 'Launch a first version', 'Grow revenue from what we have'];
// The model's options are the whole point of the chip row — they are what lets someone answer
// "restaurant" with a tap instead of typing. Append the opt-out, never replace them with it.
if (ask_contact) suggestions = suggestions.concat(["I'd rather book directly"]).slice(0, 5);

if (gen.asked_question) { S.questions.push(gen.asked_question.slice(0, 100)); if (S.questions.length > 8) S.questions = S.questions.slice(-8); }
if (x.fallback) { S.fallbacks = [...(S.fallbacks || []), `t${t}:${x.fallback}`].slice(-8); }

// ── lead write ────────────────────────────────────────────────────────────
const contactJustGiven = !!S.contact.email && S.attrs.email?.t === t;
const debounceOk = !S.last_lead_write || (Date.now() - S.last_lead_write) > 60000;
const lead_write = {
  do: handoff || contactJustGiven || (['Warm', 'Hot'].includes(quality) && debounceOk),
  sync: handoff || contactJustGiven,
  trigger: handoff ? 'handoff' : contactJustGiven ? 'contact' : 'threshold',
};
if (lead_write.do) S.last_lead_write = Date.now();

// ── analytics (no message text) ───────────────────────────────────────────
const events = [{ e: 'message_sent', p: { turn: t, intent, phase: S.phase } }];
if (t === 1) events.push({ e: 'conversation_started', p: { entry: S.entry, quick: x.payload.quick_action_id } });
if (x.docs_used?.length) events.push({ e: 'knowledge_answered', p: { support: x.support, docs: x.docs_used.length } });
if (proposed.length) events.push({ e: 'service_recommended', p: { services: S.rec.concat(S.sec_rec) } });
if (quality === 'Hot' && prevQuality !== 'Hot') events.push({ e: 'high_intent_detected', p: { signals } });
if (cta.length) events.push({ e: 'cta_shown', p: { ids: cta.map(v => v.id), reason } });
if (ask_contact) events.push({ e: 'lead_started', p: { field: ask_contact } });
if (contactJustGiven) events.push({ e: 'lead_completed', p: {} });
if (x.fallback) events.push({ e: 'fallback_triggered', p: { reason: x.fallback } });
if (x.security?.flag) events.push({ e: 'security_flag', p: { families: x.security.families } });

return [{ json: { ...x, S, reply: x.reply, cta, suggestions, ask_contact, handoff, lead_write, events, cta_reason: reason } }];

// [14] Lead mapper — Code node
// Builds the Advisor Leads row from conversation STATE, not the transcript.
// Output is a FLAT `lead` object; the "Notion · Lead Create/Update" nodes map each key to a
// Notion property, so the names below must match the database exactly (docs/03-notion-schema.md).

const x = $input.first().json;
const S = x.S;
const a = (k) => S.attrs[k]?.v || null;

const NAMES = {
  'digital-marketing': 'Digital Marketing', 'website-development': 'Website Development', 'branding-growth': 'Branding & Growth',
  'sales-lead-gen': 'Sales & Lead Generation', 'ai-automation': 'AI Automation', 'business-advisory': 'Business & Startup Advisory',
  'talent-staffing': 'Talent & Staffing', 'bookkeeping': 'Bookkeeping & Accounting',
};
const STAGE = { idea: 'Idea', pre_launch: 'Pre-launch', early_revenue: 'Early revenue', growing: 'Growing', established: 'Established' };
const TIME = { asap: 'ASAP', '1_3_months': '1-3 months', '3_6_months': '3-6 months', '6_plus': '6+ months' };

let status = 'New';
if (S.flags.vendor_pitch) status = 'Not Qualified';
else if (S.flags.handoff || S.phase === 'HANDOFF') status = 'Human Requested';
else if (S.score.quality === 'Hot' || (S.score.quality === 'Warm' && S.contact.email)) status = 'Qualified';
else if (S.flags.low_conf >= 2 || S.flags.no_kb >= 2) status = 'Needs Review';

const primary = S.rec[0];
const who = [a('team_size') ? `${a('team_size')}-person` : null, a('business_type') || 'startup'].filter(Boolean).join(' ');
const stage = STAGE[a('business_stage')] ? ` at ${STAGE[a('business_stage')].toLowerCase()} stage` : '';
const ds = a('decision_stage');
const summary = [
  `${who.charAt(0).toUpperCase() + who.slice(1)}${stage}.`,
  a('primary_problem') ? ` Problem: ${a('primary_problem')}.` : '',
  a('primary_goal') ? ` Goal: ${a('primary_goal')}${a('timeline') ? ` within ${TIME[a('timeline')] || a('timeline')}` : ''}.` : '',
  ds ? ` Visitor is ${ds === 'ready' ? 'ready to start' : ds === 'comparing' ? 'comparing providers' : 'exploring options'}${S.flags.handoff ? ' and asked to speak with the team' : ''}.` : (S.flags.handoff ? ' Visitor asked to speak with the team.' : ''),
  primary ? ` Most relevant: ${NAMES[primary]}${S.sec_rec.length ? ` with ${S.sec_rec.map(s => NAMES[s]).join(', ')}` : ''}${S.reasoning ? ` — ${S.reasoning}` : ''}.` : '',
  S.flags.pricing_asked ? ' Asked about pricing.' : '',
].join('').slice(0, 1900);

let nba = 'Review summary; no follow-up unless contact was provided.';
if (status === 'Human Requested') nba = 'Reply within one business day — the visitor asked for a person. Offer the free growth plan conversation.';
else if (status === 'Qualified') nba = `Reach out and propose a growth-plan call focused on ${primary ? NAMES[primary] : 'the described problem'}.`;
else if (status === 'Needs Review') nba = 'The advisor could not answer confidently — check for a knowledge-base gap, then follow up if contact exists.';

const notes = [
  `Understood: ${who}${stage}. Problem: ${a('primary_problem') || '—'}. Goal: ${a('primary_goal') || '—'}.`,
  `Recommended: ${primary ? NAMES[primary] : '—'}${S.sec_rec.length ? ' + ' + S.sec_rec.map(s => NAMES[s]).join(', ') : ''}. Why: ${S.reasoning || '—'}`,
  `KB entries used this turn: ${(x.docs_used || []).join(', ') || 'none'} (support ${x.support}).`,
  `CTA: ${(S.cta_history.slice(-4).map(h => `t${h.t}:${h.ids.join('+')}(${h.reason})`).join('; ')) || 'none'}.`,
  `Scores — intent ${S.score.intent}, fit ${S.score.fit}, clarity ${S.score.clarity} → ${S.score.quality}. Signals: ${(S.score.signals || []).join(', ') || '—'}.`,
  `Fallbacks: ${(S.fallbacks || []).join(', ') || 'none'}. Security flags: ${S.flags.security_hits}.`,
  `Entry page: ${S.entry}. Device: ${x.payload.device}. Trigger: ${x.lead_write.trigger}. Turns: ${S.turn}.`,
].join('\n').slice(0, 1900);

const lastUser = [...S.history].reverse().find(h => h.r === 'u')?.x || x.payload.message;

// Text properties get '' rather than null: the Notion node always sends every mapped property,
// and an empty rich_text is valid. Email and Website must be null when unknown — Notion rejects
// an empty string for those two types.
const t = (v) => (v == null ? '' : String(v));

const lead = {
  'Lead': `${S.contact.company || a('business_type') || 'Startup'} — ${a('primary_problem') || a('primary_goal') || 'advisor conversation'}`.slice(0, 80),
  'Conversation ID': S.sid,
  'Status': status,
  'Intent level': S.score.quality,
  'Visitor name': t(S.contact.name),
  'Email': S.contact.email || null,
  'Company': t(S.contact.company),
  'Website': a('website') || null,
  'Business stage': STAGE[a('business_stage')] || 'Unknown',
  'Business type': t(a('business_type')),
  'Primary problem': t(a('primary_problem')),
  'Primary goal': t(a('primary_goal')),
  'Recommended service': primary ? NAMES[primary] : 'Unclear',
  'Secondary services': S.sec_rec.map(s => NAMES[s]),
  'Timeline': TIME[a('timeline')] || 'Unknown',
  'Lead summary': summary,
  'Next best action': nba,
  'Last user message': String(lastUser).slice(0, 300),
  'Source': 'AI Advisor',
  'First seen': S.created_at,
  'Last activity': new Date().toISOString(),
  'Turns': S.turn,
  'Internal notes': notes,
};

return [{ json: { ...x, lead, lead_status: status, lead_page_id: S.lead_page_id } }];

// [15] Finalize — Code node (was "Notion Upsert + Respond")
// The lead write now happens in the "Notion · Lead Create" / "Notion · Lead Update" nodes, because
// the Code node cannot reach stored credentials. This node records whether that write landed,
// saves the session server-side, and builds the response body.
// Reached from three branches: after a create, after an update, or straight from "Write lead?" = false.

const ctx = $('Lead Mapper').first().json;
const S = ctx.S;

// ── 1. did a lead row get written this turn? ──────────────────────────────
// Only one of these nodes runs, and neither runs when lead_write.do was false — so reading a node
// that did not execute throws, and that simply means "no write happened".
let written = null;
for (const name of ['Notion · Lead Create', 'Notion · Lead Update']) {
  try {
    const r = $(name).first().json;
    if (r && r.id) { written = String(r.id); break; }
  } catch (e) { /* that branch did not run */ }
}

if (written) {
  S.lead_page_id = written;
  S.flags.lead_ok = true;
  S.flags.lead_failed = false;
} else if (ctx.lead_write?.do) {
  // We meant to write and nothing came back. The reply must not imply a record exists.
  S.flags.lead_ok = false;
  S.flags.lead_failed = true;
  if (ctx.handoff && !/book/i.test(ctx.reply)) {
    ctx.reply += "\n\nYou can also book directly from the site and mention what we discussed.";
  }
}

// ── 2. history, trimmed so stored sessions stay small ──────────────────────
const redact = (s) => String(s)
  .replace(/\b(?:\d[ -]*?){13,19}\b/g, '[number]')
  .replace(/\b\d{3}-\d{2}-\d{4}\b/g, '[id]')
  .replace(/\b(\+?\d[\d\s().-]{8,}\d)\b/g, '[phone]')
  .slice(0, 300);

S.history.push({ r: 'u', x: redact(ctx.payload.message) });
S.history.push({ r: 'a', x: String(ctx.reply).slice(0, 300) });
if (S.history.length > 8) S.history = S.history.slice(-8);   // last 4 exchanges

// ── 3. save state server-side; the browser only gets the session id ────────
const store = $getWorkflowStaticData('global');
store.sessions = store.sessions || {};
store.sessions[S.sid] = { t: Date.now(), s: S };

const response = {
  state_token: S.sid,
  reply: ctx.reply,
  cta: ctx.cta,
  suggestions: ctx.suggestions,
  state: { phase: S.phase, handoff: !!ctx.handoff, ask_contact: ctx.ask_contact || null, closing: !!S.flags.closing },
};

// Leak guard: internal vocabulary must never reach the browser.
if (/"score"|lead_quality|kb_context|system prompt|notion|n8n/i.test(JSON.stringify({ ...response, state_token: '' }))) {
  throw new Error('response leak guard tripped');
}

// Cache the reply against the turn id so a retry after a timeout costs nothing.
store.seen = store.seen || {};
store.seen[ctx.seen_key] = { t: Date.now(), r: response };

return [{ json: { response, events: ctx.events, sid: S.sid, lead_written: !!S.flags.lead_ok } }];

// Fire-and-forget analytics. Swap the console for your sink (Notion, Sheets, PostHog) if you want history.
const j = $json;
for (const e of (j.events || [])) console.log(JSON.stringify({ ts: new Date().toISOString(), sid: j.sid, event: e.e, props: e.p }));
return [{ json: j.response }];

// [7b] Split KB ids — Code node
// One item per page the router picked, so the "Notion · KB Page" node runs once per id.
// Guarded by the "Has KB?" IF node, so this never sees an empty list.
//
// No slicing here. Merge State already capped the list (6 pages / 18k chars) after ranking, and
// a second cap at a different number silently drops pages it had chosen — they then arrive with
// no body and get discarded, so the advisor answers from less than it was given.

const x = $input.first().json;
return (x.kb_ids || []).map(id => ({ json: { kb_id: id } }));
